const crypto = require('crypto');
const event = $json.body || $json;
if (!event.job_id || !event.user_id) throw new Error('job_id and user_id are required');
const body = JSON.stringify({ workflow: 'new_job_notification', job_id: event.job_id, user_id: event.user_id });
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET is not set');
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(body).digest('hex');
const base = $env.JOBPILOT_API_URL || 'http://backend:8000';
return [{json:{body,signature,delivery:'job-'+event.job_id+'-'+event.user_id,url:base+'/api/v1/automation/webhooks/new_job_notification'}}];
